@inline(__always)
private func wireFloatEquals(_ lhs: Float, _ rhs: Float) -> Bool {
    lhs.bitPattern == rhs.bitPattern
}

@inline(__always)
private func wireFloatEquals(_ lhs: Float?, _ rhs: Float?) -> Bool {
    lhs?.bitPattern == rhs?.bitPattern
}

@inline(__always)
private func wireFloatEquals(_ lhs: [Float], _ rhs: [Float]) -> Bool {
    guard lhs.count == rhs.count else { return false }
    for i in lhs.indices {
        if lhs[i].bitPattern != rhs[i].bitPattern { return false }
    }
    return true
}

@inline(__always)
private func wireFloatEquals(_ lhs: [Float]?, _ rhs: [Float]?) -> Bool {
    switch (lhs, rhs) {
    case (nil, nil):
        return true
    case (let a?, let b?):
        return wireFloatEquals(a, b)
    default:
        return false
    }
}

@inline(__always)
private func wireFloatHash(_ value: Float, into hasher: inout Hasher) {
    hasher.combine(value.bitPattern)
}

@inline(__always)
private func wireFloatHash(_ value: Float?, into hasher: inout Hasher) {
    hasher.combine(value?.bitPattern)
}

@inline(__always)
private func wireFloatHash(_ value: [Float], into hasher: inout Hasher) {
    hasher.combine(value.count)
    for element in value {
        hasher.combine(element.bitPattern)
    }
}

@inline(__always)
private func wireFloatHash(_ value: [Float]?, into hasher: inout Hasher) {
    if let array = value {
        hasher.combine(true)
        wireFloatHash(array, into: &hasher)
    } else {
        hasher.combine(false)
    }
}

