public struct FloatAnimationSpec: Equatable, Hashable, Sendable {
    public enum BitLayout {
        public static let typeShift: UInt32 = 0
        public static let typeMask: UInt32 = 0xFF
        public static let hasWrapShift: UInt32 = 8
        public static let hasWrapMask: UInt32 = 0x1
        public static let hasInitShift: UInt32 = 9
        public static let hasInitMask: UInt32 = 0x1
        public static let directionalSnapShift: UInt32 = 10
        public static let directionalSnapMask: UInt32 = 0x3
        public static let isPropagateShift: UInt32 = 12
        public static let isPropagateMask: UInt32 = 0x1
        public static let paramLenShift: UInt32 = 16
        public static let paramLenMask: UInt32 = 0xFFFF
    }
    /// The duration, then the flags word, then the curve's parameters.
    public static let durationIndex: Int = 0
    public static let flagsIndex: Int = durationIndex + 1
    public static let paramsStart: Int = flagsIndex + 1
    /// A spring spec is a zero duration marker followed by more than this many words.
    public static let springParameterCount: Int = 4
    public var duration: Float
    public var type: Int32
    public var params: [Float]
    public var initialValue: Float
    public var wrap: Float
    public var directionalSnap: Int32
    public var isPropagate: Bool
    public init(duration: Float = 1.0, type: Int32 = AnimationEasing.cubicStandard, params: [Float] = [], initialValue: Float = .nan, wrap: Float = .nan, directionalSnap: Int32 = 0, isPropagate: Bool = false) {
        self.duration = duration
        self.type = type
        self.params = params
        self.initialValue = initialValue
        self.wrap = wrap
        self.directionalSnap = directionalSnap
        self.isPropagate = isPropagate
    }
    public static func == (lhs: FloatAnimationSpec, rhs: FloatAnimationSpec) -> Bool {
        let feq: (Float, Float) -> Bool = { ($0.isNaN && $1.isNaN) || $0 == $1 }
        return feq(lhs.duration, rhs.duration)
            && lhs.type == rhs.type
            && lhs.params.count == rhs.params.count
            && zip(lhs.params, rhs.params).allSatisfy(feq)
            && feq(lhs.initialValue, rhs.initialValue)
            && feq(lhs.wrap, rhs.wrap)
            && lhs.directionalSnap == rhs.directionalSnap
            && lhs.isPropagate == rhs.isPropagate
