        for item in equation {
            buffer.writeFloat(item)
        }
        _committed = true
    }

    public static func == (lhs: ParticleCompareEquation, rhs: ParticleCompareEquation) -> Bool {
        return wireFloatEquals(lhs.equation, rhs.equation)
    }

    public func hash(into hasher: inout Hasher) {
        wireFloatHash(self.equation, into: &hasher)
    }
}

