            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(majorVersion)
        buffer.writeInt(minorVersion)
        buffer.writeInt(patchVersion)
        if Int(majorVersion) < WireExpressionConstants.headerPropertyMapMajorVersion {
            buffer.writeInt(width)
        }
        if Int(majorVersion) < WireExpressionConstants.headerPropertyMapMajorVersion {
            buffer.writeInt(height)
        }
        if Int(majorVersion) < WireExpressionConstants.headerPropertyMapMajorVersion {
            buffer.writeLong(capabilities)
        }
        if Int(majorVersion) >= WireExpressionConstants.headerPropertyMapMajorVersion {
            guard properties.count <= Swift.min(WireLimits.maxTableSize, Int(Int32.max)) else {
                throw WireError.lengthOutOfRange(field: "properties", length: properties.count, min: nil, max: Swift.min(WireLimits.maxTableSize, Int(Int32.max)))
            }
            buffer.writeInt(Int32(properties.count))
            for item in properties {
                try item.write(to: &buffer)
            }
        }
        _committed = true
    }
}

