/// Define the animation specifications for a component
public struct AnimationSpec: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .animationSpec
    public var opCode: OpCode { Self.opCode }
    /// The shifts and masks of this type's packed fields, from the schema's bit ranges.
    public enum BitLayout {
        public static let enterAnimationEnterTypeShift: UInt32 = 0
        public static let enterAnimationEnterTypeMask: UInt32 = 0xFF
        public static let enterAnimationEnterSequenceShift: UInt32 = 8
        public static let enterAnimationEnterSequenceMask: UInt32 = 0xFF
        public static let exitAnimationExitTypeShift: UInt32 = 0
        public static let exitAnimationExitTypeMask: UInt32 = 0xFF
        public static let exitAnimationExitSequenceShift: UInt32 = 8
        public static let exitAnimationExitSequenceMask: UInt32 = 0xFF
    }
    public static let defaultEnterFunctionId: Int32 = -1
    public static let defaultExitFunctionId: Int32 = -1

    /// The ID of the animation
    public var animationId: Int32
    /// Duration of the motion animation in ms
    public var motionDuration: Float
    /// The type of easing for motion
    public var motionEasingType: Int32
    /// Duration of visibility animation in ms
    public var visibilityDuration: Float
    /// The type of easing for visibility
    public var visibilityEasingType: Int32
    /// Packed entry animation type (bits 0..7) and sequence (bits 8..15)
    public var enterAnimation: Int32
    /// Packed exit animation type (bits 0..7) and sequence (bits 8..15)
    public var exitAnimation: Int32
    /// Custom enter animation function ID when enter or exit type is CUSTOM (8)
    public var enterFunctionId: Int32
    /// Custom exit animation function ID when enter or exit type is CUSTOM (8)
    public var exitFunctionId: Int32
    public var enterType: Int32 {
        return Int32((UInt32(bitPattern: enterAnimation) >> BitLayout.enterAnimationEnterTypeShift) & BitLayout.enterAnimationEnterTypeMask)
    }
    public var enterSequence: Int32 {
        return Int32((UInt32(bitPattern: enterAnimation) >> BitLayout.enterAnimationEnterSequenceShift) & BitLayout.enterAnimationEnterSequenceMask)
    }
    public var exitType: Int32 {
        return Int32((UInt32(bitPattern: exitAnimation) >> BitLayout.exitAnimationExitTypeShift) & BitLayout.exitAnimationExitTypeMask)
    }
    public var exitSequence: Int32 {
        return Int32((UInt32(bitPattern: exitAnimation) >> BitLayout.exitAnimationExitSequenceShift) & BitLayout.exitAnimationExitSequenceMask)
    }

    /// Creates a new [AnimationSpec] operation.
    /// - Parameters:
    ///   - animationId: The ID of the animation
    ///   - motionDuration: Duration of the motion animation in ms
    ///   - motionEasingType: The type of easing for motion
    ///   - visibilityDuration: Duration of visibility animation in ms
    ///   - visibilityEasingType: The type of easing for visibility
    ///   - enterAnimation: Packed entry animation type (bits 0..7) and sequence (bits 8..15)
    ///   - exitAnimation: Packed exit animation type (bits 0..7) and sequence (bits 8..15)
    ///   - enterFunctionId: Custom enter animation function ID when enter or exit type is CUSTOM (8)
    ///   - exitFunctionId: Custom exit animation function ID when enter or exit type is CUSTOM (8)
    public init(animationId: Int32 = 0, motionDuration: Float = 0.0, motionEasingType: Int32 = 0, visibilityDuration: Float = 0.0, visibilityEasingType: Int32 = 0, enterAnimation: Int32 = 0, exitAnimation: Int32 = 0, enterFunctionId: Int32 = AnimationSpec.defaultEnterFunctionId, exitFunctionId: Int32 = AnimationSpec.defaultExitFunctionId) {
        self.animationId = animationId
        self.motionDuration = motionDuration
        self.motionEasingType = motionEasingType
        self.visibilityDuration = visibilityDuration
        self.visibilityEasingType = visibilityEasingType
        self.enterAnimation = enterAnimation
        self.exitAnimation = exitAnimation
        self.enterFunctionId = enterFunctionId
        self.exitFunctionId = exitFunctionId
    }

    /// Reads and decodes a [AnimationSpec] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> AnimationSpec {
        let animationId = try buffer.readInt()
        let motionDuration = try buffer.readFloat()
        let motionEasingType = try buffer.readInt()
        let visibilityDuration = try buffer.readFloat()
        let visibilityEasingType = try buffer.readInt()
        let enterAnimation = try buffer.readInt()
        let exitAnimation = try buffer.readInt()
        let enterFunctionId: Int32
        if ((Int(enterAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom || ((Int(exitAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom {
            enterFunctionId = try buffer.readInt()
        } else {
            enterFunctionId = AnimationSpec.defaultEnterFunctionId
        }
        let exitFunctionId: Int32
        if ((Int(enterAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom || ((Int(exitAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom {
            exitFunctionId = try buffer.readInt()
        } else {
            exitFunctionId = AnimationSpec.defaultExitFunctionId
        }
        return AnimationSpec(animationId: animationId, motionDuration: motionDuration, motionEasingType: motionEasingType, visibilityDuration: visibilityDuration, visibilityEasingType: visibilityEasingType, enterAnimation: enterAnimation, exitAnimation: exitAnimation, enterFunctionId: enterFunctionId, exitFunctionId: exitFunctionId)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(animationId)
        buffer.writeFloat(motionDuration)
        buffer.writeInt(motionEasingType)
        buffer.writeFloat(visibilityDuration)
        buffer.writeInt(visibilityEasingType)
        buffer.writeInt(enterAnimation)
        buffer.writeInt(exitAnimation)
        if ((Int(enterAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom || ((Int(exitAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom {
            buffer.writeInt(enterFunctionId)
        }
        if ((Int(enterAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom || ((Int(exitAnimation) & WireExpressionConstants.animationKindMask)) == WireExpressionConstants.animationKindCustom {
            buffer.writeInt(exitFunctionId)
        }
    }

    public static func == (lhs: AnimationSpec, rhs: AnimationSpec) -> Bool {
        return lhs.animationId == rhs.animationId
            && wireFloatEquals(lhs.motionDuration, rhs.motionDuration)
            && lhs.motionEasingType == rhs.motionEasingType
            && wireFloatEquals(lhs.visibilityDuration, rhs.visibilityDuration)
            && lhs.visibilityEasingType == rhs.visibilityEasingType
            && lhs.enterAnimation == rhs.enterAnimation
            && lhs.exitAnimation == rhs.exitAnimation
            && lhs.enterFunctionId == rhs.enterFunctionId
            && lhs.exitFunctionId == rhs.exitFunctionId
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.animationId)
        wireFloatHash(self.motionDuration, into: &hasher)
        hasher.combine(self.motionEasingType)
        wireFloatHash(self.visibilityDuration, into: &hasher)
        hasher.combine(self.visibilityEasingType)
        hasher.combine(self.enterAnimation)
        hasher.combine(self.exitAnimation)
        hasher.combine(self.enterFunctionId)
        hasher.combine(self.exitFunctionId)
    }
