/// Encode a Paint object with various properties
public struct PaintData: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .paintData
    public var opCode: OpCode { Self.opCode }

    /// Serialized PaintBundle 32-bit command stream
    public var words: [Int32]

    /// Creates a new [PaintData] operation.
    /// - Parameters:
    ///   - words: Serialized PaintBundle 32-bit command stream
    public init(words: [Int32] = []) {
        self.words = words
    }

    /// Reads and decodes a [PaintData] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> PaintData {
        let _wordsCount = Int(try buffer.readInt())
        guard _wordsCount >= 0 else {
            throw WireError.invalidLength(field: "words", length: _wordsCount)
        }
        guard _wordsCount <= WireLimits.paintDataWordsMaxLength else {
            throw WireError.lengthOutOfRange(field: "words", length: _wordsCount, min: nil, max: WireLimits.paintDataWordsMaxLength)
        }
        guard _wordsCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _wordsCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var words = [Int32]()
        words.reserveCapacity(Swift.min(_wordsCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_wordsCount {
            words.append(try buffer.readInt())
        }
        return PaintData(words: words)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        guard words.count <= Swift.min(WireLimits.paintDataWordsMaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "words", length: words.count, min: nil, max: Swift.min(WireLimits.paintDataWordsMaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(words.count))
        for item in words {
            buffer.writeInt(item)
        }
        _committed = true
    }
}

