        }
        guard _expressionCount <= WireLimits.maxExpressionSize else {
            throw WireError.lengthOutOfRange(field: "expression", length: _expressionCount, min: nil, max: WireLimits.maxExpressionSize)
        }
        guard _expressionCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _expressionCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var expression = [Float]()
        expression.reserveCapacity(Swift.min(_expressionCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_expressionCount {
