            let (needed, overflow) = _animationSpecCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var animationSpec = [Float]()
        animationSpec.reserveCapacity(Swift.min(_animationSpecCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_animationSpecCount {
            animationSpec.append(try buffer.readFloat())
        }
        return FloatExpression(id: id, expression: expression, animationSpec: animationSpec)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        guard expression.count <= Int(BitLayout.packedLengthsExpressionLengthMask) else {
            throw WireError.lengthOutOfRange(field: "expression", length: expression.count, min: nil, max: Int(BitLayout.packedLengthsExpressionLengthMask))
        }
        let expressionLength: Int32 = Int32(expression.count)
        guard animationSpec.count <= Int(BitLayout.packedLengthsAnimationLengthMask) else {
            throw WireError.lengthOutOfRange(field: "animationSpec", length: animationSpec.count, min: nil, max: Int(BitLayout.packedLengthsAnimationLengthMask))
