            guard uvF16.count <= Int(Int32.max) else {
                throw WireError.lengthOutOfRange(field: "uvF16", length: uvF16.count, min: nil, max: Int(Int32.max))
            }
            buffer.writeInt(Int32(uvF16.count))
        }
        if Int(type) == WireExpressionConstants.mesh2dTypeF16Values {
            guard colorsF16.count <= Int(Int32.max) else {
                throw WireError.lengthOutOfRange(field: "colorsF16", length: colorsF16.count, min: nil, max: Int(Int32.max))
            }
            buffer.writeInt(Int32(colorsF16.count))
        }
        if Int(type) == WireExpressionConstants.mesh2dTypeF16Values {
            guard vertsF16.count <= WireLimits.addMesh2DVertsF16MaxLength else {
                throw WireError.lengthOutOfRange(field: "vertsF16", length: vertsF16.count, min: nil, max: WireLimits.addMesh2DVertsF16MaxLength)
            }
            for item in vertsF16 {
                buffer.writeShort(item)
            }
        }
        if Int(type) == WireExpressionConstants.mesh2dTypeF16Values {
            guard uvF16.count <= WireLimits.addMesh2DUvF16MaxLength else {
                throw WireError.lengthOutOfRange(field: "uvF16", length: uvF16.count, min: nil, max: WireLimits.addMesh2DUvF16MaxLength)
            }
            for item in uvF16 {
                buffer.writeShort(item)
            }
        }
        if Int(type) == WireExpressionConstants.mesh2dTypeF16Values {
            guard colorsF16.count <= WireLimits.maxMesh2dVertices else {
                throw WireError.lengthOutOfRange(field: "colorsF16", length: colorsF16.count, min: nil, max: WireLimits.maxMesh2dVertices)
            }
            for item in colorsF16 {
                buffer.writeInt(item)
            }
        }
        if Int(type) == WireExpressionConstants.mesh2dTypePathSplineStrip || Int(type) == WireExpressionConstants.mesh2dTypeSplineRoundStrip {
            guard widths.count <= Swift.min(WireLimits.maxMesh2dWidthSamples, Int(Int32.max)) else {
                throw WireError.lengthOutOfRange(field: "widths", length: widths.count, min: nil, max: Swift.min(WireLimits.maxMesh2dWidthSamples, Int(Int32.max)))
            }
            buffer.writeInt(Int32(widths.count))
            for item in widths {
                buffer.writeFloat(item)
            }
        }
        if Int(type) == WireExpressionConstants.mesh2dTypePathSplineStrip || Int(type) == WireExpressionConstants.mesh2dTypeSplineRoundStrip {
