    }

    public static func == (lhs: AddMesh2D, rhs: AddMesh2D) -> Bool {
        return lhs.meshId == rhs.meshId
            && lhs.type == rhs.type
            && lhs.layout == rhs.layout
            && lhs.uCount == rhs.uCount
            && lhs.vCount == rhs.vCount
            && lhs.flags == rhs.flags
            && lhs.aux == rhs.aux
            && wireFloatEquals(lhs.expX, rhs.expX)
            && wireFloatEquals(lhs.expY, rhs.expY)
            && wireFloatEquals(lhs.expTexU, rhs.expTexU)
            && wireFloatEquals(lhs.expTexV, rhs.expTexV)
            && wireFloatEquals(lhs.expColorA, rhs.expColorA)
            && wireFloatEquals(lhs.expColorR, rhs.expColorR)
            && wireFloatEquals(lhs.expColorG, rhs.expColorG)
            && wireFloatEquals(lhs.expColorB, rhs.expColorB)
            && wireFloatEquals(lhs.expWidth, rhs.expWidth)
            && lhs.indices == rhs.indices
            && wireFloatEquals(lhs.verts, rhs.verts)
            && wireFloatEquals(lhs.uv, rhs.uv)
            && lhs.colors == rhs.colors
            && lhs.vertsF16 == rhs.vertsF16
            && lhs.uvF16 == rhs.uvF16
            && lhs.colorsF16 == rhs.colorsF16
            && wireFloatEquals(lhs.widths, rhs.widths)
            && wireFloatEquals(lhs.widthPositions, rhs.widthPositions)
            && wireFloatEquals(lhs.antialiasWidth, rhs.antialiasWidth)
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.meshId)
        hasher.combine(self.type)
        hasher.combine(self.layout)
        hasher.combine(self.uCount)
        hasher.combine(self.vCount)
        hasher.combine(self.flags)
        hasher.combine(self.aux)
        wireFloatHash(self.expX, into: &hasher)
        wireFloatHash(self.expY, into: &hasher)
        wireFloatHash(self.expTexU, into: &hasher)
        wireFloatHash(self.expTexV, into: &hasher)
        wireFloatHash(self.expColorA, into: &hasher)
        wireFloatHash(self.expColorR, into: &hasher)
        wireFloatHash(self.expColorG, into: &hasher)
        wireFloatHash(self.expColorB, into: &hasher)
        wireFloatHash(self.expWidth, into: &hasher)
        hasher.combine(self.indices)
        wireFloatHash(self.verts, into: &hasher)
        wireFloatHash(self.uv, into: &hasher)
        hasher.combine(self.colors)
        hasher.combine(self.vertsF16)
        hasher.combine(self.uvF16)
        hasher.combine(self.colorsF16)
        wireFloatHash(self.widths, into: &hasher)
        wireFloatHash(self.widthPositions, into: &hasher)
