/// Defines a complete static path data buffer with commands and coordinates
public struct PathData: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .pathData
    public var opCode: OpCode { Self.opCode }
    public static let winding: Int32 = 0
    public static let evenOdd: Int32 = 1
    public static let inverseWinding: Int32 = 2
    public static let inverseEvenOdd: Int32 = 3
    /// The shifts and masks of this type's packed fields, from the schema's bit ranges.
    public enum BitLayout {
        public static let idAndWindingPathIdShift: UInt32 = 0
        public static let idAndWindingPathIdMask: UInt32 = 0xFFFFFF
        public static let idAndWindingWindingShift: UInt32 = 24
        public static let idAndWindingWindingMask: UInt32 = 0xFF
        public static let idAndWindingWindingLeftShift: UInt32 = 0
        public static let idAndWindingWindingRightShift: UInt32 = 24
    }

    /// Packed path ID (bits 0..23) and winding rule (bits 24..31)
    public var idAndWinding: Int32
    /// Encoded path command and coordinate float stream
    public var pathData: [Float]
    public var pathId: Int32 {
        return Int32((UInt32(bitPattern: idAndWinding) >> BitLayout.idAndWindingPathIdShift) & BitLayout.idAndWindingPathIdMask)
    }
    public var winding: Int32 {
        return (Int32(bitPattern: UInt32(bitPattern: idAndWinding) << BitLayout.idAndWindingWindingLeftShift) >> BitLayout.idAndWindingWindingRightShift)
    }
    public func decodePathCommands() -> [PathCommand] { PathCommand.decode(pathData) }

    /// Creates a new [PathData] operation.
    /// - Parameters:
    ///   - idAndWinding: Packed path ID (bits 0..23) and winding rule (bits 24..31)
    ///   - pathData: Encoded path command and coordinate float stream
    public init(idAndWinding: Int32 = 0, pathData: [Float] = []) {
        self.idAndWinding = idAndWinding
        self.pathData = pathData
    }

    /// Reads and decodes a [PathData] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> PathData {
        let idAndWinding = try buffer.readInt()
        let _pathDataCount = Int(try buffer.readInt())
        guard _pathDataCount >= 0 else {
            throw WireError.invalidLength(field: "pathData", length: _pathDataCount)
        }
        guard _pathDataCount <= WireLimits.pathDataPathDataMaxLength else {
            throw WireError.lengthOutOfRange(field: "pathData", length: _pathDataCount, min: nil, max: WireLimits.pathDataPathDataMaxLength)
        }
        guard _pathDataCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _pathDataCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var pathData = [Float]()
        pathData.reserveCapacity(Swift.min(_pathDataCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_pathDataCount {
            pathData.append(try buffer.readFloat())
        }
        return PathData(idAndWinding: idAndWinding, pathData: pathData)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(idAndWinding)
        guard pathData.count <= Swift.min(WireLimits.pathDataPathDataMaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "pathData", length: pathData.count, min: nil, max: Swift.min(WireLimits.pathDataPathDataMaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(pathData.count))
        for item in pathData {
            buffer.writeFloat(item)
        }
        _committed = true
    }

    public static func == (lhs: PathData, rhs: PathData) -> Bool {
        return lhs.idAndWinding == rhs.idAndWinding
            && wireFloatEquals(lhs.pathData, rhs.pathData)
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.idAndWinding)
        wireFloatHash(self.pathData, into: &hasher)
    }
}

