    public var opCode: OpCode { Self.opCode }
    public static let string: Int32 = 0
    public static let float: Int32 = 1
    public static let color: Int32 = 2
    public static let image: Int32 = 3
    public static let int: Int32 = 4
    public static let long: Int32 = 5
    public static let path: Int32 = 6
    public static let floatArray: Int32 = 6

    /// Variable ID
    public var varId: Int32
    /// Type of variable (0=STRING, 1=FLOAT, 2=COLOR, 3=IMAGE, 4=INT, 5=LONG, 6=FLOAT_ARRAY/PATH)
    public var varType: Int32
    /// Human readable identifier name
    public var name: String

    /// Creates a new [NamedVariable] operation.
    /// - Parameters:
    ///   - varId: Variable ID
    ///   - varType: Type of variable (0=STRING, 1=FLOAT, 2=COLOR, 3=IMAGE, 4=INT, 5=LONG, 6=FLOAT_ARRAY/PATH)
    ///   - name: Human readable identifier name
    public init(varId: Int32 = 0, varType: Int32 = 0, name: String = "") {
        self.varId = varId
        self.varType = varType
        self.name = name
    }

    /// Reads and decodes a [NamedVariable] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> NamedVariable {
        let varId = try buffer.readInt()
        let varType = try buffer.readInt()
        let name = try buffer.readUTF8(maxLength: WireLimits.maxStringSize)
        return NamedVariable(varId: varId, varType: varType, name: name)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(varId)
        buffer.writeInt(varType)
        try buffer.writeUTF8(name, maxLength: WireLimits.maxStringSize)
        _committed = true
    }
}

