/// Defines an integer variable computed via Reverse Polish Notation (RPN) expression evaluation
public struct IntegerExpression: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .integerExpression
    public var opCode: OpCode { Self.opCode }

    /// Integer expression ID
    public var id: Int32
    /// Bitmask indicating which elements are operators or IDs
    public var mask: Int32
    /// RPN integer expression tokens
    public var values: [Int32]

    /// Creates a new [IntegerExpression] operation.
    /// - Parameters:
    ///   - id: Integer expression ID
    ///   - mask: Bitmask indicating which elements are operators or IDs
    ///   - values: RPN integer expression tokens
    public init(id: Int32 = 0, mask: Int32 = 0, values: [Int32] = []) {
        self.id = id
        self.mask = mask
        self.values = values
    }

    /// Reads and decodes a [IntegerExpression] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> IntegerExpression {
        let id = try buffer.readInt()
        let mask = try buffer.readInt()
        let _valuesCount = Int(try buffer.readInt())
        guard _valuesCount >= 0 else {
            throw WireError.invalidLength(field: "values", length: _valuesCount)
        }
        guard _valuesCount <= WireLimits.integerExpressionValuesMaxLength else {
            throw WireError.lengthOutOfRange(field: "values", length: _valuesCount, min: nil, max: WireLimits.integerExpressionValuesMaxLength)
        }
        guard _valuesCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _valuesCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var values = [Int32]()
        values.reserveCapacity(Swift.min(_valuesCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_valuesCount {
            values.append(try buffer.readInt())
        }
        return IntegerExpression(id: id, mask: mask, values: values)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeInt(mask)
        guard values.count <= Swift.min(WireLimits.integerExpressionValuesMaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "values", length: values.count, min: nil, max: Swift.min(WireLimits.integerExpressionValuesMaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(values.count))
        for item in values {
            buffer.writeInt(item)
        }
        _committed = true
    }
}

/// Encode a collection of named variable IDs
public struct DataMapIds: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .dataMapIds
    public var opCode: OpCode { Self.opCode }

    /// Data map ID
    public var id: Int32
    /// Named typed variable entries
    public var entries: [DataMapEntry]

    /// Creates a new [DataMapIds] operation.
    /// - Parameters:
    ///   - id: Data map ID
    ///   - entries: Named typed variable entries
    public init(id: Int32 = 0, entries: [DataMapEntry] = []) {
        self.id = id
        self.entries = entries
    }

    /// Reads and decodes a [DataMapIds] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> DataMapIds {
        let id = try buffer.readInt()
        let _entriesCount = Int(try buffer.readInt())
        guard _entriesCount >= 0 else {
            throw WireError.invalidLength(field: "entries", length: _entriesCount)
        }
        guard _entriesCount <= WireLimits.maxDataMapSize else {
            throw WireError.lengthOutOfRange(field: "entries", length: _entriesCount, min: nil, max: WireLimits.maxDataMapSize)
        }
        guard _entriesCount <= buffer.remaining / DataMapEntry.minWireBytes else {
            let (needed, overflow) = _entriesCount.multipliedReportingOverflow(by: DataMapEntry.minWireBytes)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var entries = [DataMapEntry]()
        entries.reserveCapacity(Swift.min(_entriesCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_entriesCount {
            entries.append(try DataMapEntry.read(from: &buffer))
        }
        return DataMapIds(id: id, entries: entries)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        guard entries.count <= Swift.min(WireLimits.maxDataMapSize, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "entries", length: entries.count, min: nil, max: Swift.min(WireLimits.maxDataMapSize, Int(Int32.max)))
        }
        buffer.writeInt(Int32(entries.count))
        for item in entries {
            try item.write(to: &buffer)
        }
        _committed = true
    }
}

