/// Draw a bitmap with scaling and alignment options
public struct DrawBitmapScaled: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .drawBitmapScaled
    public var opCode: OpCode { Self.opCode }
    public static let scaleNone: Int32 = 0
    public static let scaleInside: Int32 = 1
    public static let scaleFillWidth: Int32 = 2
    public static let scaleFillHeight: Int32 = 3
    public static let scaleFit: Int32 = 4
    public static let scaleCrop: Int32 = 5
    public static let scaleFillBounds: Int32 = 6
    public static let scaleFixedScale: Int32 = 7
    /// The shifts and masks of this type's packed fields, from the schema's bit ranges.
    public enum BitLayout {
        public static let scaleTypeScaleModeShift: UInt32 = 0
        public static let scaleTypeScaleModeMask: UInt32 = 0xFF
        public static let scaleTypeDereferenceImageIdShift: UInt32 = 8
        public static let scaleTypeDereferenceImageIdMask: UInt32 = 0x1
    }

    /// The ID of the bitmap
    public var imageId: Int32
    /// The left side of the source image
    public var srcLeft: Float
    /// The top of the source image
    public var srcTop: Float
    /// The right side of the source image
    public var srcRight: Float
    /// The bottom of the source image
    public var srcBottom: Float
    /// The left side of the destination
    public var dstLeft: Float
    /// The top of the destination
    public var dstTop: Float
    /// The right side of the destination
    public var dstRight: Float
    /// The bottom of the destination
    public var dstBottom: Float
    /// Type of scaling to apply
    public var scaleType: Int32
    /// Factor for fixed scale
    public var scaleFactor: Float
    /// The ID of the content description string
    public var cdId: Int32
    public var scaleMode: Int32 {
        return Int32((UInt32(bitPattern: scaleType) >> BitLayout.scaleTypeScaleModeShift) & BitLayout.scaleTypeScaleModeMask)
    }
    public var dereferenceImageId: Int32 {
        return Int32((UInt32(bitPattern: scaleType) >> BitLayout.scaleTypeDereferenceImageIdShift) & BitLayout.scaleTypeDereferenceImageIdMask)
    }

    /// Creates a new [DrawBitmapScaled] operation.
    /// - Parameters:
    ///   - imageId: The ID of the bitmap
    ///   - srcLeft: The left side of the source image
    ///   - srcTop: The top of the source image
    ///   - srcRight: The right side of the source image
    ///   - srcBottom: The bottom of the source image
    ///   - dstLeft: The left side of the destination
    ///   - dstTop: The top of the destination
    ///   - dstRight: The right side of the destination
    ///   - dstBottom: The bottom of the destination
    ///   - scaleType: Type of scaling to apply
    ///   - scaleFactor: Factor for fixed scale
    ///   - cdId: The ID of the content description string
    public init(imageId: Int32 = 0, srcLeft: Float = 0.0, srcTop: Float = 0.0, srcRight: Float = 0.0, srcBottom: Float = 0.0, dstLeft: Float = 0.0, dstTop: Float = 0.0, dstRight: Float = 0.0, dstBottom: Float = 0.0, scaleType: Int32 = 0, scaleFactor: Float = 0.0, cdId: Int32 = 0) {
        self.imageId = imageId
        self.srcLeft = srcLeft
        self.srcTop = srcTop
        self.srcRight = srcRight
        self.srcBottom = srcBottom
        self.dstLeft = dstLeft
        self.dstTop = dstTop
        self.dstRight = dstRight
        self.dstBottom = dstBottom
        self.scaleType = scaleType
        self.scaleFactor = scaleFactor
        self.cdId = cdId
    }

    /// Reads and decodes a [DrawBitmapScaled] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> DrawBitmapScaled {
        let imageId = try buffer.readInt()
        let srcLeft = try buffer.readFloat()
        let srcTop = try buffer.readFloat()
        let srcRight = try buffer.readFloat()
        let srcBottom = try buffer.readFloat()
        let dstLeft = try buffer.readFloat()
        let dstTop = try buffer.readFloat()
        let dstRight = try buffer.readFloat()
        let dstBottom = try buffer.readFloat()
        let scaleType = try buffer.readInt()
        let scaleFactor = try buffer.readFloat()
        let cdId = try buffer.readInt()
        return DrawBitmapScaled(imageId: imageId, srcLeft: srcLeft, srcTop: srcTop, srcRight: srcRight, srcBottom: srcBottom, dstLeft: dstLeft, dstTop: dstTop, dstRight: dstRight, dstBottom: dstBottom, scaleType: scaleType, scaleFactor: scaleFactor, cdId: cdId)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(imageId)
        buffer.writeFloat(srcLeft)
        buffer.writeFloat(srcTop)
        buffer.writeFloat(srcRight)
        buffer.writeFloat(srcBottom)
        buffer.writeFloat(dstLeft)
        buffer.writeFloat(dstTop)
        buffer.writeFloat(dstRight)
        buffer.writeFloat(dstBottom)
        buffer.writeInt(scaleType)
        buffer.writeFloat(scaleFactor)
        buffer.writeInt(cdId)
    }

    public static func == (lhs: DrawBitmapScaled, rhs: DrawBitmapScaled) -> Bool {
        return lhs.imageId == rhs.imageId
            && wireFloatEquals(lhs.srcLeft, rhs.srcLeft)
            && wireFloatEquals(lhs.srcTop, rhs.srcTop)
            && wireFloatEquals(lhs.srcRight, rhs.srcRight)
            && wireFloatEquals(lhs.srcBottom, rhs.srcBottom)
            && wireFloatEquals(lhs.dstLeft, rhs.dstLeft)
            && wireFloatEquals(lhs.dstTop, rhs.dstTop)
            && wireFloatEquals(lhs.dstRight, rhs.dstRight)
            && wireFloatEquals(lhs.dstBottom, rhs.dstBottom)
            && lhs.scaleType == rhs.scaleType
            && wireFloatEquals(lhs.scaleFactor, rhs.scaleFactor)
            && lhs.cdId == rhs.cdId
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.imageId)
        wireFloatHash(self.srcLeft, into: &hasher)
        wireFloatHash(self.srcTop, into: &hasher)
        wireFloatHash(self.srcRight, into: &hasher)
        wireFloatHash(self.srcBottom, into: &hasher)
        wireFloatHash(self.dstLeft, into: &hasher)
        wireFloatHash(self.dstTop, into: &hasher)
        wireFloatHash(self.dstRight, into: &hasher)
        wireFloatHash(self.dstBottom, into: &hasher)
        hasher.combine(self.scaleType)
        wireFloatHash(self.scaleFactor, into: &hasher)
        hasher.combine(self.cdId)
    }
}

