/// Look up a string from a collection via index
public struct TextLookup: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .textLookup
    public var opCode: OpCode { Self.opCode }

    /// The ID of the resulting text
    public var textId: Int32
    /// The ID of the string collection
    public var dataSetId: Int32
    /// The index of the string to retrieve
    public var index: Float

    /// Creates a new [TextLookup] operation.
    /// - Parameters:
    ///   - textId: The ID of the resulting text
    ///   - dataSetId: The ID of the string collection
    ///   - index: The index of the string to retrieve
    public init(textId: Int32 = 0, dataSetId: Int32 = 0, index: Float = 0.0) {
        self.textId = textId
        self.dataSetId = dataSetId
        self.index = index
    }

    /// Reads and decodes a [TextLookup] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> TextLookup {
        let textId = try buffer.readInt()
        let dataSetId = try buffer.readInt()
        let index = try buffer.readFloat()
        return TextLookup(textId: textId, dataSetId: dataSetId, index: index)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(textId)
        buffer.writeInt(dataSetId)
        buffer.writeFloat(index)
    }

    public static func == (lhs: TextLookup, rhs: TextLookup) -> Bool {
        return lhs.textId == rhs.textId
            && lhs.dataSetId == rhs.dataSetId
            && wireFloatEquals(lhs.index, rhs.index)
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.textId)
        hasher.combine(self.dataSetId)
        wireFloatHash(self.index, into: &hasher)
    }
}

