/// Measure text dimensions and store the result in a float variable
public struct TextMeasure: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .textMeasure
    public var opCode: OpCode { Self.opCode }
    public static let measureWidth: Int32 = 0
    public static let measureHeight: Int32 = 1
    public static let measureLeft: Int32 = 2
    public static let measureRight: Int32 = 3
    public static let measureTop: Int32 = 4
    public static let measureBottom: Int32 = 5
    /// The shifts and masks of this type's packed fields, from the schema's bit ranges.
    public enum BitLayout {
        public static let typeMeasureKindShift: UInt32 = 0
        public static let typeMeasureKindMask: UInt32 = 0xFF
        public static let typeMeasureFlagsShift: UInt32 = 8
        public static let typeMeasureFlagsMask: UInt32 = 0xFFFFFF
        public static let typeMeasureFlagsLeftShift: UInt32 = 0
        public static let typeMeasureFlagsRightShift: UInt32 = 8
    }

    /// The ID of the float variable to store the result
    public var id: Int32
    /// The ID of the text to measure
    public var textId: Int32
    /// The type of measurement (WIDTH, HEIGHT, etc.)
    public var type: Int32
    public var measureKind: Int32 {
        return Int32((UInt32(bitPattern: type) >> BitLayout.typeMeasureKindShift) & BitLayout.typeMeasureKindMask)
    }
    public var measureFlags: Int32 {
        return (Int32(bitPattern: UInt32(bitPattern: type) << BitLayout.typeMeasureFlagsLeftShift) >> BitLayout.typeMeasureFlagsRightShift)
    }

    /// Creates a new [TextMeasure] operation.
    /// - Parameters:
    ///   - id: The ID of the float variable to store the result
    ///   - textId: The ID of the text to measure
    ///   - type: The type of measurement (WIDTH, HEIGHT, etc.)
    public init(id: Int32 = 0, textId: Int32 = 0, type: Int32 = 0) {
        self.id = id
        self.textId = textId
        self.type = type
    }

    /// Reads and decodes a [TextMeasure] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> TextMeasure {
        let id = try buffer.readInt()
        let textId = try buffer.readInt()
        let type = try buffer.readInt()
        return TextMeasure(id: id, textId: textId, type: type)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeInt(textId)
        buffer.writeInt(type)
    }
}

