/// Defines a float variable derived from touch interactions and gestures
public struct TouchExpression: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .touchExpression
    public var opCode: OpCode { Self.opCode }
    /// The shifts and masks of this type's packed fields, from the schema's bit ranges.
    public enum BitLayout {
        public static let expressionLenExpLenShift: UInt32 = 0
        public static let expressionLenExpLenMask: UInt32 = 0xFFFF
        public static let stopModeAndLenStopLenShift: UInt32 = 0
        public static let stopModeAndLenStopLenMask: UInt32 = 0xFFFF
        public static let stopModeAndLenStopModeShift: UInt32 = 16
        public static let stopModeAndLenStopModeMask: UInt32 = 0xFFFF
        public static let stopModeAndLenStopModeLeftShift: UInt32 = 0
        public static let stopModeAndLenStopModeRightShift: UInt32 = 16
    }

    /// Output float variable ID
    public var id: Int32
    /// Initial touch value
    public var value: Float
    /// Minimum touch bound (or NaN if flags bit set)
    public var min: Float
    /// Maximum touch bound
    public var max: Float
    /// Velocity parameter or reference
    public var velocityId: Float
    /// Haptic and touch behavior flags
    public var touchEffects: Int32
    /// Touch mapping RPN expression
    public var expression: [Float]
    /// Touch stop mode
    public var stopMode: Int32
    /// Stop positions/notches specification
    public var stopSpec: [Float]
    /// Spring or easing specification parameters
    public var easingSpec: [Float]

    /// Creates a new [TouchExpression] operation.
    /// - Parameters:
    ///   - id: Output float variable ID
    ///   - value: Initial touch value
    ///   - min: Minimum touch bound (or NaN if flags bit set)
    ///   - max: Maximum touch bound
    ///   - velocityId: Velocity parameter or reference
    ///   - touchEffects: Haptic and touch behavior flags
    ///   - expression: Touch mapping RPN expression
    ///   - stopMode: Touch stop mode
    ///   - stopSpec: Stop positions/notches specification
    ///   - easingSpec: Spring or easing specification parameters
    public init(id: Int32 = 0, value: Float = 0.0, min: Float = 0.0, max: Float = 0.0, velocityId: Float = 0.0, touchEffects: Int32 = 0, expression: [Float] = [], stopMode: Int32 = 0, stopSpec: [Float] = [], easingSpec: [Float] = []) {
        self.id = id
        self.value = value
        self.min = min
        self.max = max
        self.velocityId = velocityId
        self.touchEffects = touchEffects
        self.expression = expression
        self.stopMode = stopMode
        self.stopSpec = stopSpec
        self.easingSpec = easingSpec
    }

    /// Reads and decodes a [TouchExpression] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> TouchExpression {
        let id = try buffer.readInt()
        let value = try buffer.readFloat()
        let min = try buffer.readFloat()
        let max = try buffer.readFloat()
        let velocityId = try buffer.readFloat()
        let touchEffects = try buffer.readInt()
        let raw_expressionLen = try buffer.readInt()
        let expLen = Int32((UInt32(bitPattern: raw_expressionLen) >> BitLayout.expressionLenExpLenShift) & BitLayout.expressionLenExpLenMask)
        let _expressionCount = Int(expLen)
        guard _expressionCount >= 0 else {
            throw WireError.invalidLength(field: "expression", length: _expressionCount)
        }
        guard _expressionCount <= WireLimits.maxExpressionSize else {
            throw WireError.lengthOutOfRange(field: "expression", length: _expressionCount, min: nil, max: WireLimits.maxExpressionSize)
        }
        guard _expressionCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _expressionCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var expression = [Float]()
        expression.reserveCapacity(Swift.min(_expressionCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_expressionCount {
            expression.append(try buffer.readFloat())
        }
        let raw_stopModeAndLen = try buffer.readInt()
        let stopLen = Int32((UInt32(bitPattern: raw_stopModeAndLen) >> BitLayout.stopModeAndLenStopLenShift) & BitLayout.stopModeAndLenStopLenMask)
        let stopMode = (Int32(bitPattern: UInt32(bitPattern: raw_stopModeAndLen) << BitLayout.stopModeAndLenStopModeLeftShift) >> BitLayout.stopModeAndLenStopModeRightShift)
        let _stopSpecCount = Int(stopLen)
        guard _stopSpecCount >= 0 else {
            throw WireError.invalidLength(field: "stopSpec", length: _stopSpecCount)
        }
        guard _stopSpecCount <= WireLimits.maxTouchStops else {
            throw WireError.lengthOutOfRange(field: "stopSpec", length: _stopSpecCount, min: nil, max: WireLimits.maxTouchStops)
        }
        guard _stopSpecCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _stopSpecCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var stopSpec = [Float]()
        stopSpec.reserveCapacity(Swift.min(_stopSpecCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_stopSpecCount {
            stopSpec.append(try buffer.readFloat())
        }
        let _easingSpecCount = Int(try buffer.readInt())
        guard _easingSpecCount >= 0 else {
            throw WireError.invalidLength(field: "easingSpec", length: _easingSpecCount)
        }
        guard _easingSpecCount <= WireLimits.maxEasingLen else {
            throw WireError.lengthOutOfRange(field: "easingSpec", length: _easingSpecCount, min: nil, max: WireLimits.maxEasingLen)
        }
        guard _easingSpecCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _easingSpecCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var easingSpec = [Float]()
        easingSpec.reserveCapacity(Swift.min(_easingSpecCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_easingSpecCount {
            easingSpec.append(try buffer.readFloat())
        }
        return TouchExpression(id: id, value: value, min: min, max: max, velocityId: velocityId, touchEffects: touchEffects, expression: expression, stopMode: stopMode, stopSpec: stopSpec, easingSpec: easingSpec)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeFloat(value)
        buffer.writeFloat(min)
        buffer.writeFloat(max)
        buffer.writeFloat(velocityId)
        buffer.writeInt(touchEffects)
        guard expression.count <= Int(BitLayout.expressionLenExpLenMask) else {
            throw WireError.lengthOutOfRange(field: "expression", length: expression.count, min: nil, max: Int(BitLayout.expressionLenExpLenMask))
        }
        let expLen: Int32 = Int32(expression.count)
        buffer.writeInt(Int32(bitPattern: ((UInt32(bitPattern: Int32(expLen)) & BitLayout.expressionLenExpLenMask) << BitLayout.expressionLenExpLenShift)))
        guard expression.count <= WireLimits.maxExpressionSize else {
            throw WireError.lengthOutOfRange(field: "expression", length: expression.count, min: nil, max: WireLimits.maxExpressionSize)
        }
        for item in expression {
            buffer.writeFloat(item)
        }
        guard stopSpec.count <= Int(BitLayout.stopModeAndLenStopLenMask) else {
            throw WireError.lengthOutOfRange(field: "stopSpec", length: stopSpec.count, min: nil, max: Int(BitLayout.stopModeAndLenStopLenMask))
        }
        let stopLen: Int32 = Int32(stopSpec.count)
        buffer.writeInt(Int32(bitPattern: ((UInt32(bitPattern: Int32(stopLen)) & BitLayout.stopModeAndLenStopLenMask) << BitLayout.stopModeAndLenStopLenShift) | ((UInt32(bitPattern: Int32(stopMode)) & BitLayout.stopModeAndLenStopModeMask) << BitLayout.stopModeAndLenStopModeShift)))
        guard stopSpec.count <= WireLimits.maxTouchStops else {
            throw WireError.lengthOutOfRange(field: "stopSpec", length: stopSpec.count, min: nil, max: WireLimits.maxTouchStops)
        }
        for item in stopSpec {
            buffer.writeFloat(item)
        }
        guard easingSpec.count <= Swift.min(WireLimits.maxEasingLen, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "easingSpec", length: easingSpec.count, min: nil, max: Swift.min(WireLimits.maxEasingLen, Int(Int32.max)))
        }
        buffer.writeInt(Int32(easingSpec.count))
        for item in easingSpec {
            buffer.writeFloat(item)
        }
        _committed = true
    }

    public static func == (lhs: TouchExpression, rhs: TouchExpression) -> Bool {
        return lhs.id == rhs.id
            && wireFloatEquals(lhs.value, rhs.value)
            && wireFloatEquals(lhs.min, rhs.min)
            && wireFloatEquals(lhs.max, rhs.max)
            && wireFloatEquals(lhs.velocityId, rhs.velocityId)
            && lhs.touchEffects == rhs.touchEffects
            && wireFloatEquals(lhs.expression, rhs.expression)
            && lhs.stopMode == rhs.stopMode
            && wireFloatEquals(lhs.stopSpec, rhs.stopSpec)
            && wireFloatEquals(lhs.easingSpec, rhs.easingSpec)
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.id)
        wireFloatHash(self.value, into: &hasher)
        wireFloatHash(self.min, into: &hasher)
        wireFloatHash(self.max, into: &hasher)
        wireFloatHash(self.velocityId, into: &hasher)
        hasher.combine(self.touchEffects)
        wireFloatHash(self.expression, into: &hasher)
        hasher.combine(self.stopMode)
        wireFloatHash(self.stopSpec, into: &hasher)
        wireFloatHash(self.easingSpec, into: &hasher)
    }
}

/// Interpolate between two paths and store the result in a new path ID
public struct PathTween: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .pathTween
    public var opCode: OpCode { Self.opCode }

    /// The ID of the resulting interpolated path
    public var outId: Int32
    /// The ID of the first source path
    public var pathId1: Int32
    /// The ID of the second source path
    public var pathId2: Int32
    /// The interpolation factor [0..1]
    public var tween: Float

    /// Creates a new [PathTween] operation.
    /// - Parameters:
    ///   - outId: The ID of the resulting interpolated path
    ///   - pathId1: The ID of the first source path
    ///   - pathId2: The ID of the second source path
    ///   - tween: The interpolation factor [0..1]
    public init(outId: Int32 = 0, pathId1: Int32 = 0, pathId2: Int32 = 0, tween: Float = 0.0) {
        self.outId = outId
        self.pathId1 = pathId1
        self.pathId2 = pathId2
        self.tween = tween
    }

    /// Reads and decodes a [PathTween] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> PathTween {
        let outId = try buffer.readInt()
        let pathId1 = try buffer.readInt()
        let pathId2 = try buffer.readInt()
        let tween = try buffer.readFloat()
        return PathTween(outId: outId, pathId1: pathId1, pathId2: pathId2, tween: tween)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(outId)
        buffer.writeInt(pathId1)
        buffer.writeInt(pathId2)
        buffer.writeFloat(tween)
    }

    public static func == (lhs: PathTween, rhs: PathTween) -> Bool {
        return lhs.outId == rhs.outId
            && lhs.pathId1 == rhs.pathId1
            && lhs.pathId2 == rhs.pathId2
            && wireFloatEquals(lhs.tween, rhs.tween)
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.outId)
        hasher.combine(self.pathId1)
        hasher.combine(self.pathId2)
        wireFloatHash(self.tween, into: &hasher)
    }
}

