/// Embeds font glyph layout, character metrics, and glyph page mappings for bitmap font rendering
public struct BitmapFontData: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .bitmapFontData
    public var opCode: OpCode { Self.opCode }
    /// The shifts and masks of this type's packed fields, from the schema's bit ranges.
    public enum BitLayout {
        public static let versionAndNumGlyphsNumGlyphsShift: UInt32 = 0
        public static let versionAndNumGlyphsNumGlyphsMask: UInt32 = 0xFFFF
        public static let versionAndNumGlyphsVersionShift: UInt32 = 16
        public static let versionAndNumGlyphsVersionMask: UInt32 = 0xFFFF
        public static let versionAndNumGlyphsVersionLeftShift: UInt32 = 0
        public static let versionAndNumGlyphsVersionRightShift: UInt32 = 16
    }

    /// Bitmap font ID
    public var id: Int32
    /// Glyph definitions
    public var glyphs: [Glyph]
    /// Optional kerning adjustment pairs (present when version >= 1)
    public var kerningTable: [KerningPair]

    /// Creates a new [BitmapFontData] operation.
    /// - Parameters:
    ///   - id: Bitmap font ID
    ///   - glyphs: Glyph definitions
    ///   - kerningTable: Optional kerning adjustment pairs (present when version >= 1)
    public init(id: Int32 = 0, glyphs: [Glyph] = [], kerningTable: [KerningPair] = []) {
        self.id = id
        self.glyphs = glyphs
        self.kerningTable = kerningTable
    }

    /// Reads and decodes a [BitmapFontData] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> BitmapFontData {
        let id = try buffer.readInt()
        let raw_versionAndNumGlyphs = try buffer.readInt()
        let numGlyphs = Int32((UInt32(bitPattern: raw_versionAndNumGlyphs) >> BitLayout.versionAndNumGlyphsNumGlyphsShift) & BitLayout.versionAndNumGlyphsNumGlyphsMask)
        let version = (Int32(bitPattern: UInt32(bitPattern: raw_versionAndNumGlyphs) << BitLayout.versionAndNumGlyphsVersionLeftShift) >> BitLayout.versionAndNumGlyphsVersionRightShift)
        let _glyphsCount = Int(numGlyphs)
        guard _glyphsCount >= 0 else {
            throw WireError.invalidLength(field: "glyphs", length: _glyphsCount)
        }
        guard _glyphsCount <= buffer.remaining / Glyph.minWireBytes else {
            let (needed, overflow) = _glyphsCount.multipliedReportingOverflow(by: Glyph.minWireBytes)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var glyphs = [Glyph]()
        glyphs.reserveCapacity(Swift.min(_glyphsCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_glyphsCount {
            glyphs.append(try Glyph.read(from: &buffer))
        }
        let kerningTable: [KerningPair]
        if Int(version) >= WireExpressionConstants.bitmapFontVersionKerning {
            let _kerningTableCount = Int(UInt16(bitPattern: try buffer.readShort()))
            guard _kerningTableCount >= 0 else {
                throw WireError.invalidLength(field: "kerningTable", length: _kerningTableCount)
            }
            guard _kerningTableCount <= buffer.remaining / KerningPair.minWireBytes else {
                let (needed, overflow) = _kerningTableCount.multipliedReportingOverflow(by: KerningPair.minWireBytes)
                throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
            }
            var kerningTableTmp = [KerningPair]()
            kerningTableTmp.reserveCapacity(Swift.min(_kerningTableCount, WireLimits.maxInitialCapacity))
            for _ in 0..<_kerningTableCount {
                kerningTableTmp.append(try KerningPair.read(from: &buffer))
            }
            kerningTable = kerningTableTmp
        } else {
            kerningTable = []
        }
        return BitmapFontData(id: id, glyphs: glyphs, kerningTable: kerningTable)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        guard glyphs.count <= Int(BitLayout.versionAndNumGlyphsNumGlyphsMask) else {
            throw WireError.lengthOutOfRange(field: "glyphs", length: glyphs.count, min: nil, max: Int(BitLayout.versionAndNumGlyphsNumGlyphsMask))
        }
        let numGlyphs: Int32 = Int32(glyphs.count)
        let version: Int32 = (!kerningTable.isEmpty ? 1 : 0)
        buffer.writeInt(Int32(bitPattern: ((UInt32(bitPattern: Int32(numGlyphs)) & BitLayout.versionAndNumGlyphsNumGlyphsMask) << BitLayout.versionAndNumGlyphsNumGlyphsShift) | ((UInt32(bitPattern: Int32(version)) & BitLayout.versionAndNumGlyphsVersionMask) << BitLayout.versionAndNumGlyphsVersionShift)))
        for item in glyphs {
            try item.write(to: &buffer)
        }
        if Int(version) >= WireExpressionConstants.bitmapFontVersionKerning {
            guard kerningTable.count <= Int(UInt16.max) else {
                throw WireError.lengthOutOfRange(field: "kerningTable", length: kerningTable.count, min: nil, max: Int(UInt16.max))
            }
            buffer.writeShort(Int16(truncatingIfNeeded: kerningTable.count))
            for item in kerningTable {
                try item.write(to: &buffer)
            }
        }
        _committed = true
    }
}

