    /// Creates a new [ImageAttribute] operation.
    /// - Parameters:
    ///   - id: The ID of the float variable to store the result
    ///   - imageId: The ID of the image variable to extract from
    ///   - type: The type of property to extract (0=WIDTH, 1=HEIGHT)
    ///   - args: Support for additional arguments
    public init(id: Int32 = 0, imageId: Int32 = 0, type: Int16 = 0, args: [Int32] = []) {
        self.id = id
        self.imageId = imageId
        self.type = type
        self.args = args
    }

    /// Reads and decodes a [ImageAttribute] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> ImageAttribute {
        let id = try buffer.readInt()
        let imageId = try buffer.readInt()
        let type = try buffer.readShort()
        let _argsCount = Int(try buffer.readShort())
        guard _argsCount >= 0 else {
            throw WireError.invalidLength(field: "args", length: _argsCount)
        }
        guard _argsCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _argsCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var args = [Int32]()
        args.reserveCapacity(Swift.min(_argsCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_argsCount {
            args.append(try buffer.readInt())
        }
        return ImageAttribute(id: id, imageId: imageId, type: type, args: args)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeInt(imageId)
        buffer.writeShort(type)
        guard args.count <= Int(Int16.max) else {
            throw WireError.lengthOutOfRange(field: "args", length: args.count, min: nil, max: Int(Int16.max))
        }
        buffer.writeShort(Int16(truncatingIfNeeded: args.count))
        for item in args {
            buffer.writeInt(item)
        }
        _committed = true
    }
}

