/// Generates a dynamic 2D path from mathematical expressions across a variable range
public struct PathExpression: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .pathExpression
    public var opCode: OpCode { Self.opCode }

    /// Output path ID
    public var id: Int32
    /// Path expression flags (polar, loop, etc.)
    public var flags: Int32
    /// Parameter range minimum
    public var min: Float
    /// Parameter range maximum
    public var max: Float
    /// Sample count
    public var count: Float
    /// X/radius RPN expression
    public var expressionX: [Float]
    /// Y/angle RPN expression (may be empty)
    public var expressionY: [Float]

    /// Creates a new [PathExpression] operation.
    /// - Parameters:
    ///   - id: Output path ID
    ///   - flags: Path expression flags (polar, loop, etc.)
    ///   - min: Parameter range minimum
    ///   - max: Parameter range maximum
    ///   - count: Sample count
    ///   - expressionX: X/radius RPN expression
    ///   - expressionY: Y/angle RPN expression (may be empty)
    public init(id: Int32 = 0, flags: Int32 = 0, min: Float = 0.0, max: Float = 0.0, count: Float = 0.0, expressionX: [Float] = [], expressionY: [Float] = []) {
        self.id = id
        self.flags = flags
        self.min = min
        self.max = max
        self.count = count
        self.expressionX = expressionX
        self.expressionY = expressionY
    }

    /// Reads and decodes a [PathExpression] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> PathExpression {
        let id = try buffer.readInt()
        let flags = try buffer.readInt()
        let min = try buffer.readFloat()
        let max = try buffer.readFloat()
        let count = try buffer.readFloat()
        let _expressionXCount = Int(try buffer.readInt())
        guard _expressionXCount >= 0 else {
            throw WireError.invalidLength(field: "expressionX", length: _expressionXCount)
        }
        guard _expressionXCount <= WireLimits.maxExpressionSize else {
            throw WireError.lengthOutOfRange(field: "expressionX", length: _expressionXCount, min: nil, max: WireLimits.maxExpressionSize)
        }
        guard _expressionXCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _expressionXCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var expressionX = [Float]()
        expressionX.reserveCapacity(Swift.min(_expressionXCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_expressionXCount {
            expressionX.append(try buffer.readFloat())
        }
        let _expressionYCount = Int(try buffer.readInt())
        guard _expressionYCount >= 0 else {
            throw WireError.invalidLength(field: "expressionY", length: _expressionYCount)
        }
        guard _expressionYCount <= WireLimits.maxExpressionSize else {
            throw WireError.lengthOutOfRange(field: "expressionY", length: _expressionYCount, min: nil, max: WireLimits.maxExpressionSize)
        }
        guard _expressionYCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _expressionYCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var expressionY = [Float]()
        expressionY.reserveCapacity(Swift.min(_expressionYCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_expressionYCount {
            expressionY.append(try buffer.readFloat())
        }
        return PathExpression(id: id, flags: flags, min: min, max: max, count: count, expressionX: expressionX, expressionY: expressionY)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeInt(flags)
        buffer.writeFloat(min)
        buffer.writeFloat(max)
        buffer.writeFloat(count)
        guard expressionX.count <= Swift.min(WireLimits.maxExpressionSize, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "expressionX", length: expressionX.count, min: nil, max: Swift.min(WireLimits.maxExpressionSize, Int(Int32.max)))
        }
        buffer.writeInt(Int32(expressionX.count))
        for item in expressionX {
            buffer.writeFloat(item)
        }
        guard expressionY.count <= Swift.min(WireLimits.maxExpressionSize, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "expressionY", length: expressionY.count, min: nil, max: Swift.min(WireLimits.maxExpressionSize, Int(Int32.max)))
        }
        buffer.writeInt(Int32(expressionY.count))
        for item in expressionY {
            buffer.writeFloat(item)
        }
        _committed = true
    }

    public static func == (lhs: PathExpression, rhs: PathExpression) -> Bool {
        return lhs.id == rhs.id
            && lhs.flags == rhs.flags
            && wireFloatEquals(lhs.min, rhs.min)
            && wireFloatEquals(lhs.max, rhs.max)
            && wireFloatEquals(lhs.count, rhs.count)
            && wireFloatEquals(lhs.expressionX, rhs.expressionX)
            && wireFloatEquals(lhs.expressionY, rhs.expressionY)
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.id)
        hasher.combine(self.flags)
        wireFloatHash(self.min, into: &hasher)
        wireFloatHash(self.max, into: &hasher)
        wireFloatHash(self.count, into: &hasher)
        wireFloatHash(self.expressionX, into: &hasher)
        wireFloatHash(self.expressionY, into: &hasher)
    }
}

/// Compares particle variables to evaluate conditional state transitions or recycling
public struct ParticlesCompare: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .particlesCompare
    public var opCode: OpCode { Self.opCode }

    /// Particle system ID
    public var id: Int32
    /// Comparison flags
    public var flags: Int16
    /// Minimum threshold
    public var min: Float
    /// Maximum threshold
    public var max: Float
    /// Comparison RPN expression
    public var condition: [Float]
    /// First branch particle equations
    public var equations1: [ParticleCompareEquation]
    /// Second branch particle equations
    public var equations2: [ParticleCompareEquation]

    /// Creates a new [ParticlesCompare] operation.
    /// - Parameters:
    ///   - id: Particle system ID
    ///   - flags: Comparison flags
    ///   - min: Minimum threshold
    ///   - max: Maximum threshold
    ///   - condition: Comparison RPN expression
    ///   - equations1: First branch particle equations
    ///   - equations2: Second branch particle equations
    public init(id: Int32 = 0, flags: Int16 = 0, min: Float = 0.0, max: Float = 0.0, condition: [Float] = [], equations1: [ParticleCompareEquation] = [], equations2: [ParticleCompareEquation] = []) {
        self.id = id
        self.flags = flags
        self.min = min
        self.max = max
        self.condition = condition
        self.equations1 = equations1
        self.equations2 = equations2
    }

    /// Reads and decodes a [ParticlesCompare] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> ParticlesCompare {
        let id = try buffer.readInt()
        let flags = try buffer.readShort()
        let min = try buffer.readFloat()
        let max = try buffer.readFloat()
        let _conditionCount = Int(try buffer.readInt())
        guard _conditionCount >= 0 else {
            throw WireError.invalidLength(field: "condition", length: _conditionCount)
        }
        guard _conditionCount <= WireLimits.particlesCompareConditionMaxLength else {
            throw WireError.lengthOutOfRange(field: "condition", length: _conditionCount, min: nil, max: WireLimits.particlesCompareConditionMaxLength)
        }
        guard _conditionCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _conditionCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var condition = [Float]()
        condition.reserveCapacity(Swift.min(_conditionCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_conditionCount {
            condition.append(try buffer.readFloat())
        }
        let _equations1Count = Int(try buffer.readInt())
        guard _equations1Count >= 0 else {
            throw WireError.invalidLength(field: "equations1", length: _equations1Count)
        }
        guard _equations1Count <= WireLimits.particlesCompareEquations1MaxLength else {
            throw WireError.lengthOutOfRange(field: "equations1", length: _equations1Count, min: nil, max: WireLimits.particlesCompareEquations1MaxLength)
        }
        guard _equations1Count <= buffer.remaining / ParticleCompareEquation.minWireBytes else {
            let (needed, overflow) = _equations1Count.multipliedReportingOverflow(by: ParticleCompareEquation.minWireBytes)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var equations1 = [ParticleCompareEquation]()
        equations1.reserveCapacity(Swift.min(_equations1Count, WireLimits.maxInitialCapacity))
        for _ in 0..<_equations1Count {
            equations1.append(try ParticleCompareEquation.read(from: &buffer))
        }
        let _equations2Count = Int(try buffer.readInt())
        guard _equations2Count >= 0 else {
            throw WireError.invalidLength(field: "equations2", length: _equations2Count)
        }
        guard _equations2Count <= WireLimits.particlesCompareEquations2MaxLength else {
            throw WireError.lengthOutOfRange(field: "equations2", length: _equations2Count, min: nil, max: WireLimits.particlesCompareEquations2MaxLength)
        }
        guard _equations2Count <= buffer.remaining / ParticleCompareEquation.minWireBytes else {
            let (needed, overflow) = _equations2Count.multipliedReportingOverflow(by: ParticleCompareEquation.minWireBytes)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var equations2 = [ParticleCompareEquation]()
        equations2.reserveCapacity(Swift.min(_equations2Count, WireLimits.maxInitialCapacity))
        for _ in 0..<_equations2Count {
            equations2.append(try ParticleCompareEquation.read(from: &buffer))
        }
        return ParticlesCompare(id: id, flags: flags, min: min, max: max, condition: condition, equations1: equations1, equations2: equations2)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeShort(flags)
        buffer.writeFloat(min)
        buffer.writeFloat(max)
        guard condition.count <= Swift.min(WireLimits.particlesCompareConditionMaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "condition", length: condition.count, min: nil, max: Swift.min(WireLimits.particlesCompareConditionMaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(condition.count))
        for item in condition {
            buffer.writeFloat(item)
        }
        guard equations1.count <= Swift.min(WireLimits.particlesCompareEquations1MaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "equations1", length: equations1.count, min: nil, max: Swift.min(WireLimits.particlesCompareEquations1MaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(equations1.count))
        for item in equations1 {
            try item.write(to: &buffer)
        }
        guard equations2.count <= Swift.min(WireLimits.particlesCompareEquations2MaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "equations2", length: equations2.count, min: nil, max: Swift.min(WireLimits.particlesCompareEquations2MaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(equations2.count))
        for item in equations2 {
            try item.write(to: &buffer)
        }
        _committed = true
    }

    public static func == (lhs: ParticlesCompare, rhs: ParticlesCompare) -> Bool {
        return lhs.id == rhs.id
            && lhs.flags == rhs.flags
            && wireFloatEquals(lhs.min, rhs.min)
            && wireFloatEquals(lhs.max, rhs.max)
            && wireFloatEquals(lhs.condition, rhs.condition)
            && lhs.equations1 == rhs.equations1
            && lhs.equations2 == rhs.equations2
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.id)
        hasher.combine(self.flags)
        wireFloatHash(self.min, into: &hasher)
        wireFloatHash(self.max, into: &hasher)
        wireFloatHash(self.condition, into: &hasher)
        hasher.combine(self.equations1)
        hasher.combine(self.equations2)
    }
}

