/// Defines a synthesized sound recipe with pitch, rate, and channel volumes
public struct SoundExpression: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .soundExpression
    public var opCode: OpCode { Self.opCode }

    /// Sound expression ID
    public var id: Int32
    /// Left channel volume
    public var leftVolume: Float
    /// Right channel volume
    public var rightVolume: Float
    /// Playback rate
    public var rate: Float
    /// Sound modulation expression
    public var params: [Float]

    /// Creates a new [SoundExpression] operation.
    /// - Parameters:
    ///   - id: Sound expression ID
    ///   - leftVolume: Left channel volume
    ///   - rightVolume: Right channel volume
    ///   - rate: Playback rate
    ///   - params: Sound modulation expression
    public init(id: Int32 = 0, leftVolume: Float = 0.0, rightVolume: Float = 0.0, rate: Float = 0.0, params: [Float] = []) {
        self.id = id
        self.leftVolume = leftVolume
        self.rightVolume = rightVolume
        self.rate = rate
        self.params = params
    }

    /// Reads and decodes a [SoundExpression] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> SoundExpression {
        let id = try buffer.readInt()
        let leftVolume = try buffer.readFloat()
        let rightVolume = try buffer.readFloat()
        let rate = try buffer.readFloat()
        let _paramsCount = Int(try buffer.readInt())
        guard _paramsCount >= 0 else {
            throw WireError.invalidLength(field: "params", length: _paramsCount)
        }
        guard _paramsCount <= WireLimits.soundExpressionParamsMaxLength else {
            throw WireError.lengthOutOfRange(field: "params", length: _paramsCount, min: nil, max: WireLimits.soundExpressionParamsMaxLength)
        }
        guard _paramsCount <= buffer.remaining / MemoryLayout<Int32>.size else {
            let (needed, overflow) = _paramsCount.multipliedReportingOverflow(by: MemoryLayout<Int32>.size)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var params = [Float]()
        params.reserveCapacity(Swift.min(_paramsCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_paramsCount {
            params.append(try buffer.readFloat())
        }
        return SoundExpression(id: id, leftVolume: leftVolume, rightVolume: rightVolume, rate: rate, params: params)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeFloat(leftVolume)
        buffer.writeFloat(rightVolume)
        buffer.writeFloat(rate)
        guard params.count <= Swift.min(WireLimits.soundExpressionParamsMaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "params", length: params.count, min: nil, max: Swift.min(WireLimits.soundExpressionParamsMaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(params.count))
        for item in params {
            buffer.writeFloat(item)
        }
        _committed = true
    }

    public static func == (lhs: SoundExpression, rhs: SoundExpression) -> Bool {
        return lhs.id == rhs.id
            && wireFloatEquals(lhs.leftVolume, rhs.leftVolume)
            && wireFloatEquals(lhs.rightVolume, rhs.rightVolume)
            && wireFloatEquals(lhs.rate, rhs.rate)
            && wireFloatEquals(lhs.params, rhs.params)
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.id)
        wireFloatHash(self.leftVolume, into: &hasher)
        wireFloatHash(self.rightVolume, into: &hasher)
        wireFloatHash(self.rate, into: &hasher)
        wireFloatHash(self.params, into: &hasher)
    }
}

