/// Text layout implementation
public struct TextLayout: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .textLayout
    public var opCode: OpCode { Self.opCode }
    public static let fontStyleNormal: Int32 = 0
    public static let fontStyleItalic: Int32 = 1
    public static let left: Int32 = 1
    public static let right: Int32 = 2
    public static let center: Int32 = 3
    public static let justify: Int32 = 4
    public static let start: Int32 = 5
    public static let end: Int32 = 6
    public static let overflowClip: Int32 = 1
    public static let overflowVisible: Int32 = 2
    public static let overflowEllipsis: Int32 = 3
    public static let overflowStartEllipsis: Int32 = 4
    public static let overflowMiddleEllipsis: Int32 = 5
    /// The shifts and masks of this type's packed fields, from the schema's bit ranges.
    public enum BitLayout {
        public static let textAlignAlignmentShift: UInt32 = 0
        public static let textAlignAlignmentMask: UInt32 = 0xFFFF
        public static let textAlignAlignmentLeftShift: UInt32 = 16
        public static let textAlignAlignmentRightShift: UInt32 = 16
        public static let textAlignIsDynamicColorShift: UInt32 = 16
        public static let textAlignIsDynamicColorMask: UInt32 = 0x1
        public static let textAlignUpperFlagsShift: UInt32 = 17
        public static let textAlignUpperFlagsMask: UInt32 = 0x7FFF
        public static let textAlignUpperFlagsLeftShift: UInt32 = 0
        public static let textAlignUpperFlagsRightShift: UInt32 = 17
    }

    /// Unique ID for this component
    public var componentId: Int32
    /// ID used to match components for animation purposes
    public var animationId: Int32
    /// The ID of the text to display
    public var textId: Int32
    /// The text color (ARGB)
    public var color: Int32
    /// The font size in pixels
    public var fontSize: Float
    /// The font style (0=normal, 1=italic)
    public var fontStyle: Int32
    /// The font weight [1..1000]
    public var fontWeight: Float
    /// The ID of the font family name string
    public var fontFamilyId: Int32
    /// The text alignment and flags
    public var textAlign: Int32
    /// The overflow strategy
    public var overflow: Int32
    /// The maximum number of lines
    public var maxLines: Int32
    public var alignment: Int32 {
        return (Int32(bitPattern: UInt32(bitPattern: textAlign) << BitLayout.textAlignAlignmentLeftShift) >> BitLayout.textAlignAlignmentRightShift)
    }
    public var isDynamicColor: Int32 {
        return Int32((UInt32(bitPattern: textAlign) >> BitLayout.textAlignIsDynamicColorShift) & BitLayout.textAlignIsDynamicColorMask)
    }
    public var upperFlags: Int32 {
        return (Int32(bitPattern: UInt32(bitPattern: textAlign) << BitLayout.textAlignUpperFlagsLeftShift) >> BitLayout.textAlignUpperFlagsRightShift)
    }

    /// Creates a new [TextLayout] operation.
    /// - Parameters:
    ///   - componentId: Unique ID for this component
    ///   - animationId: ID used to match components for animation purposes
    ///   - textId: The ID of the text to display
    ///   - color: The text color (ARGB)
    ///   - fontSize: The font size in pixels
    ///   - fontStyle: The font style (0=normal, 1=italic)
    ///   - fontWeight: The font weight [1..1000]
    ///   - fontFamilyId: The ID of the font family name string
    ///   - textAlign: The text alignment and flags
    ///   - overflow: The overflow strategy
    ///   - maxLines: The maximum number of lines
    public init(componentId: Int32 = 0, animationId: Int32 = 0, textId: Int32 = 0, color: Int32 = 0, fontSize: Float = 0.0, fontStyle: Int32 = 0, fontWeight: Float = 0.0, fontFamilyId: Int32 = 0, textAlign: Int32 = 0, overflow: Int32 = 0, maxLines: Int32 = 0) {
        self.componentId = componentId
        self.animationId = animationId
        self.textId = textId
        self.color = color
        self.fontSize = fontSize
        self.fontStyle = fontStyle
        self.fontWeight = fontWeight
        self.fontFamilyId = fontFamilyId
        self.textAlign = textAlign
        self.overflow = overflow
        self.maxLines = maxLines
    }

    /// Reads and decodes a [TextLayout] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> TextLayout {
        let componentId = try buffer.readInt()
        let animationId = try buffer.readInt()
        let textId = try buffer.readInt()
        let color = try buffer.readInt()
        let fontSize = try buffer.readFloat()
        let fontStyle = try buffer.readInt()
        let fontWeight = try buffer.readFloat()
        let fontFamilyId = try buffer.readInt()
        let textAlign = try buffer.readInt()
        let overflow = try buffer.readInt()
        let maxLines = try buffer.readInt()
        return TextLayout(componentId: componentId, animationId: animationId, textId: textId, color: color, fontSize: fontSize, fontStyle: fontStyle, fontWeight: fontWeight, fontFamilyId: fontFamilyId, textAlign: textAlign, overflow: overflow, maxLines: maxLines)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(componentId)
        buffer.writeInt(animationId)
        buffer.writeInt(textId)
        buffer.writeInt(color)
        buffer.writeFloat(fontSize)
        buffer.writeInt(fontStyle)
        buffer.writeFloat(fontWeight)
        buffer.writeInt(fontFamilyId)
        buffer.writeInt(textAlign)
        buffer.writeInt(overflow)
        buffer.writeInt(maxLines)
    }

    public static func == (lhs: TextLayout, rhs: TextLayout) -> Bool {
        return lhs.componentId == rhs.componentId
            && lhs.animationId == rhs.animationId
            && lhs.textId == rhs.textId
            && lhs.color == rhs.color
            && wireFloatEquals(lhs.fontSize, rhs.fontSize)
            && lhs.fontStyle == rhs.fontStyle
            && wireFloatEquals(lhs.fontWeight, rhs.fontWeight)
            && lhs.fontFamilyId == rhs.fontFamilyId
            && lhs.textAlign == rhs.textAlign
            && lhs.overflow == rhs.overflow
            && lhs.maxLines == rhs.maxLines
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(self.componentId)
        hasher.combine(self.animationId)
        hasher.combine(self.textId)
        hasher.combine(self.color)
        wireFloatHash(self.fontSize, into: &hasher)
        hasher.combine(self.fontStyle)
        wireFloatHash(self.fontWeight, into: &hasher)
        hasher.combine(self.fontFamilyId)
        hasher.combine(self.textAlign)
        hasher.combine(self.overflow)
        hasher.combine(self.maxLines)
    }
}

