/// Define transformations (scale, rotation, alpha) for a component
public struct GraphicsLayerModifierOperation: Equatable, Hashable, Sendable {
    public static let opCode: OpCode = .graphicsLayerModifierOperation
    public var opCode: OpCode { Self.opCode }

    /// Tagged graphics layer attributes
    public var attributes: [GraphicsLayerAttribute]

    /// Creates a new [GraphicsLayerModifierOperation] operation.
    /// - Parameters:
    ///   - attributes: Tagged graphics layer attributes
    public init(attributes: [GraphicsLayerAttribute] = []) {
        self.attributes = attributes
    }

    /// Reads and decodes a [GraphicsLayerModifierOperation] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> GraphicsLayerModifierOperation {
        let _attributesCount = Int(try buffer.readInt())
        guard _attributesCount >= 0 else {
            throw WireError.invalidLength(field: "attributes", length: _attributesCount)
        }
        guard _attributesCount <= WireLimits.graphicsLayerModifierOperationAttributesMaxLength else {
            throw WireError.lengthOutOfRange(field: "attributes", length: _attributesCount, min: nil, max: WireLimits.graphicsLayerModifierOperationAttributesMaxLength)
        }
        guard _attributesCount <= buffer.remaining / GraphicsLayerAttribute.minWireBytes else {
            let (needed, overflow) = _attributesCount.multipliedReportingOverflow(by: GraphicsLayerAttribute.minWireBytes)
            throw WireError.underflow(needed: overflow ? Int.max : needed, remaining: buffer.remaining)
        }
        var attributes = [GraphicsLayerAttribute]()
        attributes.reserveCapacity(Swift.min(_attributesCount, WireLimits.maxInitialCapacity))
        for _ in 0..<_attributesCount {
            attributes.append(try GraphicsLayerAttribute.read(from: &buffer))
        }
        return GraphicsLayerModifierOperation(attributes: attributes)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        let _startCount = buffer.data.count
        var _committed = false
        defer {
            if !_committed {
                buffer.truncate(to: _startCount)
            }
        }
        buffer.writeByte(Self.opCode.rawValue)
        guard attributes.count <= Swift.min(WireLimits.graphicsLayerModifierOperationAttributesMaxLength, Int(Int32.max)) else {
            throw WireError.lengthOutOfRange(field: "attributes", length: attributes.count, min: nil, max: Swift.min(WireLimits.graphicsLayerModifierOperationAttributesMaxLength, Int(Int32.max)))
        }
        buffer.writeInt(Int32(attributes.count))
        for item in attributes {
            try item.write(to: &buffer)
        }
        _committed = true
    }
}

