    public var enabled: Bool
    /// Whether the component is clickable
    public var clickable: Bool

    /// Creates a new [CoreSemantics] operation.
    /// - Parameters:
    ///   - contentDescriptionId: ID of the content description string
    ///   - role: The accessibility role (BUTTON, CHECKBOX, etc.)
    ///   - textId: ID of the text string
    ///   - stateDescriptionId: ID of the state description string
    ///   - mode: Semantics merge mode (SET, MERGE)
    ///   - enabled: Whether the component is enabled
    ///   - clickable: Whether the component is clickable
    public init(contentDescriptionId: Int32 = 0, role: UInt8 = 0, textId: Int32 = 0, stateDescriptionId: Int32 = 0, mode: UInt8 = 0, enabled: Bool = false, clickable: Bool = false) {
        self.contentDescriptionId = contentDescriptionId
        self.role = role
        self.textId = textId
        self.stateDescriptionId = stateDescriptionId
        self.mode = mode
        self.enabled = enabled
        self.clickable = clickable
    }

    /// Reads and decodes a [CoreSemantics] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws(WireError) -> CoreSemantics {
        let contentDescriptionId = try buffer.readInt()
        let role = try buffer.readByte()
        let textId = try buffer.readInt()
        let stateDescriptionId = try buffer.readInt()
        let mode = try buffer.readByte()
        let enabled = try buffer.readBoolean()
        let clickable = try buffer.readBoolean()
        return CoreSemantics(contentDescriptionId: contentDescriptionId, role: role, textId: textId, stateDescriptionId: stateDescriptionId, mode: mode, enabled: enabled, clickable: clickable)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws(WireError) {
        buffer.writeByte(Self.opCode.rawValue)
        buffer.writeInt(contentDescriptionId)
        buffer.writeByte(role)
        buffer.writeInt(textId)
        buffer.writeInt(stateDescriptionId)
        buffer.writeByte(mode)
        buffer.writeBoolean(enabled)
        buffer.writeBoolean(clickable)
    }
}

