/// Typed value stored in a modern (v1.1+) RemoteCompose header property.
public enum HeaderPropertyValue: Equatable, Hashable, Sendable {
    case int(Int32)
    case float(Float)
    case long(Int64)
    case string(String)
    case unknown(dataType: Int32, payload: [UInt8])

    public static func == (lhs: HeaderPropertyValue, rhs: HeaderPropertyValue) -> Bool {
        switch (lhs, rhs) {
        case (.int(let a), .int(let b)):
            return a == b
        case (.float(let a), .float(let b)):
            return wireFloatEquals(a, b)
        case (.long(let a), .long(let b)):
            return a == b
        case (.string(let a), .string(let b)):
            return a == b
        case (.unknown(let aDt, let aPayload), .unknown(let bDt, let bPayload)):
            return aDt == bDt && aPayload == bPayload
        default:
            return false
        }
    }

    public func hash(into hasher: inout Hasher) {
        switch self {
        case .int(let val):
            hasher.combine("int")
            hasher.combine(val)
        case .float(let val):
            hasher.combine("float")
            wireFloatHash(val, into: &hasher)
        case .long(let val):
            hasher.combine("long")
            hasher.combine(val)
        case .string(let val):
            hasher.combine("string")
            hasher.combine(val)
        case .unknown(let dt, let payload):
            hasher.combine("unknown")
            hasher.combine(dt)
            hasher.combine(payload)
        }
    }
}

/// Ordered header property entry in a modern (v1.1+) RemoteCompose document.
public struct WireHeaderProperty: Equatable, Hashable, Sendable {
    public var key: Int32
    public var value: HeaderPropertyValue

    public init(key: Int32, value: HeaderPropertyValue) {
        self.key = key
        self.value = value
    }
}

/// Wire-level representation of a RemoteCompose binary document.
public struct WireDocument: Equatable, Hashable, Sendable {
    public static let maxHeaderProperties: Int = 1000
    public static let maxOperationCount: Int = 100_000
    public static let defaultDimension: Int32 = HeaderConstants.defaultDimension
    public static let magicNumber: Int32 = HeaderConstants.magicNumber
    public static let maxHeaderStringLength: Int = 4000

    public var majorVersion: Int32
    public var minorVersion: Int32
    public var patchVersion: Int32
    public var width: Int32
    public var height: Int32
    public var capabilities: Int64
    public var isModernHeader: Bool
    public var properties: [WireHeaderProperty]
    public var operations: [WireOperation]

    public init(
        majorVersion: Int32 = HeaderConstants.defaultMajorVersion,
        minorVersion: Int32 = HeaderConstants.defaultMinorVersion,
        patchVersion: Int32 = HeaderConstants.defaultPatchVersion,
        width: Int32? = nil,
        height: Int32? = nil,
        capabilities: Int64? = nil,
        isModernHeader: Bool = false,
        properties: [WireHeaderProperty] = [],
        operations: [WireOperation] = []
    ) {
        let modern = isModernHeader || !properties.isEmpty
        var resolvedWidth: Int32 = modern ? Self.defaultDimension : 0
        var resolvedHeight: Int32 = modern ? Self.defaultDimension : 0
        var resolvedCapabilities: Int64 = 0
        for prop in properties {
            switch (prop.key, prop.value) {
            case (HeaderKey.docWidth, .int(let val)):
                resolvedWidth = val
            case (HeaderKey.docHeight, .int(let val)):
                resolvedHeight = val
            case (HeaderKey.docProfiles, .int(let val)):
                resolvedCapabilities = Int64(UInt32(bitPattern: val))
            case (HeaderKey.docProfiles, .long(let val)):
                resolvedCapabilities = val
            default:
                break
            }
        }
        self.majorVersion = majorVersion
        self.minorVersion = minorVersion
        self.patchVersion = patchVersion
        self.width = width ?? resolvedWidth
        self.height = height ?? resolvedHeight
        self.capabilities = capabilities ?? resolvedCapabilities
        self.isModernHeader = modern
        self.properties = properties
        self.operations = operations
    }

    /// Deserializes a WireDocument from raw binary bytes.
    public static func load(from data: [UInt8], maxOperations: Int = maxOperationCount) throws(WireError) -> WireDocument {
        return try loadImpl(from: data, maxOperations: maxOperations, evaluateSkip: false, playerApiLevel: 0, playerProfiles: 0)
    }

    /// Deserializes a WireDocument evaluating conditional skip operations against the target player.
    public static func loadForPlayer(
        from data: [UInt8],
        playerApiLevel: Int32,
        playerProfiles: Int32 = 0,
        maxOperations: Int = maxOperationCount
    ) throws(WireError) -> WireDocument {
        return try loadImpl(
            from: data,
            maxOperations: maxOperations,
            evaluateSkip: true,
            playerApiLevel: playerApiLevel,
            playerProfiles: playerProfiles
        )
    }

    private static func loadImpl(
        from data: [UInt8],
        maxOperations: Int,
        evaluateSkip: Bool,
        playerApiLevel: Int32,
        playerProfiles: Int32
    ) throws(WireError) -> WireDocument {
        var buffer = WireBuffer(data: data)
        var doc = WireDocument()
        guard buffer.available else { return doc }

        let headerOp = try buffer.readByte()
        guard headerOp == OpCode.header.rawValue else {
            throw WireError.expectedHeaderOpCode(actual: headerOp)
        }
        let rawMajor = try buffer.readInt()
        doc.minorVersion = try buffer.readInt()
        doc.patchVersion = try buffer.readInt()
        if (UInt32(bitPattern: rawMajor) & HeaderLayout.magicMask) == UInt32(bitPattern: magicNumber) {
            doc.isModernHeader = true
            doc.majorVersion = rawMajor & HeaderLayout.versionMask
            doc.width = defaultDimension
            doc.height = defaultDimension
            let numProps = Int(try buffer.readInt())
            guard numProps >= 0 && numProps <= maxHeaderProperties else {
                throw WireError.lengthOutOfRange(field: "headerProperties", length: numProps, min: 0, max: maxHeaderProperties)
            }
            guard numProps <= buffer.remaining / HeaderLayout.propertyMinWireBytes else {
                throw WireError.underflow(needed: numProps * HeaderLayout.propertyMinWireBytes, remaining: buffer.remaining)
            }
            doc.properties.reserveCapacity(numProps)
            for _ in 0..<numProps {
                let rawTag = try buffer.readShort()
                let itemLen = Int(UInt16(bitPattern: try buffer.readShort()))
                let dataType = Int32(rawTag) >> HeaderLayout.propertyTypeShift
                let key = Int32(rawTag) & HeaderLayout.propertyKeyMask
                switch dataType {
                case HeaderConstants.dataTypeInt:
                    let val = try buffer.readInt()
                    doc.properties.append(WireHeaderProperty(key: key, value: .int(val)))
                    if key == HeaderKey.docWidth { doc.width = val }
                    else if key == HeaderKey.docHeight { doc.height = val }
                    else if key == HeaderKey.docProfiles { doc.capabilities = Int64(UInt32(bitPattern: val)) }
                    else if key == HeaderKey.compress && val != 0 {
                        throw WireError.compressedDocumentUnsupported
                    }
                case HeaderConstants.dataTypeFloat:
                    let val = try buffer.readFloat()
                    doc.properties.append(WireHeaderProperty(key: key, value: .float(val)))
                case HeaderConstants.dataTypeLong:
                    let val = try buffer.readLong()
                    doc.properties.append(WireHeaderProperty(key: key, value: .long(val)))
                    if key == HeaderKey.docProfiles { doc.capabilities = val }
                    else if key == HeaderKey.compress && val != 0 {
                        throw WireError.compressedDocumentUnsupported
                    }
                case HeaderConstants.dataTypeString:
                    let val = try buffer.readUTF8(maxLength: maxHeaderStringLength)
                    doc.properties.append(WireHeaderProperty(key: key, value: .string(val)))
                default:
                    let payload = try buffer.readBytes(count: itemLen)
                    doc.properties.append(WireHeaderProperty(key: key, value: .unknown(dataType: dataType, payload: payload)))
                }
            }
        } else if rawMajor >= 0 && rawMajor <= HeaderLayout.versionMask {
            doc.isModernHeader = false
            doc.majorVersion = rawMajor
