    /// Serializes this document to raw binary bytes, preserving modern headers.
    public func save() throws(WireError) -> [UInt8] {
        guard majorVersion >= 0 && majorVersion <= HeaderLayout.versionMask else {
            throw WireError.invalidFieldValue(owner: "WireDocument", field: "majorVersion", detail: "majorVersion \(majorVersion) out of range (0..65535)")
        }
        var buffer = WireBuffer()
        buffer.writeByte(OpCode.header.rawValue)
        if isModernHeader || !properties.isEmpty {
            var outProps = properties
            if let idx = outProps.lastIndex(where: { if $0.key != HeaderKey.docWidth { return false }; if case .int(_) = $0.value { return true }; return false }) {
                outProps[idx].value = .int(width)
            } else if width != Self.defaultDimension {
                outProps.append(WireHeaderProperty(key: HeaderKey.docWidth, value: .int(width)))
            }
            if let idx = outProps.lastIndex(where: { if $0.key != HeaderKey.docHeight { return false }; if case .int(_) = $0.value { return true }; return false }) {
                outProps[idx].value = .int(height)
            } else if height != Self.defaultDimension {
                outProps.append(WireHeaderProperty(key: HeaderKey.docHeight, value: .int(height)))
            }
            let capValue: HeaderPropertyValue
            if capabilities >= 0 && capabilities <= Int64(UInt32.max) {
                capValue = .int(Int32(truncatingIfNeeded: capabilities))
            } else {
                capValue = .long(capabilities)
            }
            if let idx = outProps.lastIndex(where: { if $0.key != HeaderKey.docProfiles { return false }; switch $0.value { case .int(_), .long(_): return true; default: return false } }) {
                let matchesExisting: Bool
                switch outProps[idx].value {
                case .int(let existing):
                    matchesExisting = Int64(UInt32(bitPattern: existing)) == capabilities
                case .long(let existing):
                    matchesExisting = existing == capabilities
                default:
                    matchesExisting = false
                }
                if !matchesExisting {
                    outProps[idx].value = capValue
                }
            } else if capabilities != 0 {
                outProps.append(WireHeaderProperty(key: HeaderKey.docProfiles, value: capValue))
            }
            guard outProps.count <= Self.maxHeaderProperties else {
                throw WireError.lengthOutOfRange(field: "headerProperties", length: outProps.count, min: 0, max: Self.maxHeaderProperties)
            }
            buffer.writeInt(Self.magicNumber | (majorVersion & HeaderLayout.versionMask))
            buffer.writeInt(minorVersion)
            buffer.writeInt(patchVersion)
            buffer.writeInt(Int32(outProps.count))
            for prop in outProps {
                guard prop.key >= 0 && prop.key <= HeaderLayout.propertyKeyMask else {
                    throw WireError.invalidFieldValue(owner: "WireDocument", field: "headerPropertyKey", detail: "Property key \(prop.key) out of range (0..63)")
                }
                switch prop.value {
                case .int(let val):
                    buffer.writeShort(Int16(truncatingIfNeeded: (prop.key & HeaderLayout.propertyKeyMask) | (HeaderConstants.dataTypeInt << HeaderLayout.propertyTypeShift)))
                    buffer.writeShort(Int16(MemoryLayout<Int32>.size))
                    buffer.writeInt(val)
                case .float(let val):
                    buffer.writeShort(Int16(truncatingIfNeeded: (prop.key & HeaderLayout.propertyKeyMask) | (HeaderConstants.dataTypeFloat << HeaderLayout.propertyTypeShift)))
                    buffer.writeShort(Int16(MemoryLayout<Float>.size))
                    buffer.writeFloat(val)
                case .long(let val):
                    buffer.writeShort(Int16(truncatingIfNeeded: (prop.key & HeaderLayout.propertyKeyMask) | (HeaderConstants.dataTypeLong << HeaderLayout.propertyTypeShift)))
                    buffer.writeShort(Int16(MemoryLayout<Int64>.size))
                    buffer.writeLong(val)
                case .string(let val):
                    let utf8Count = val.utf8.count
                    guard utf8Count <= Self.maxHeaderStringLength else {
                        throw WireError.lengthOutOfRange(field: "headerStringProperty", length: utf8Count, min: nil, max: Self.maxHeaderStringLength)
                    }
                    buffer.writeShort(Int16(truncatingIfNeeded: (prop.key & HeaderLayout.propertyKeyMask) | (HeaderConstants.dataTypeString << HeaderLayout.propertyTypeShift)))
                    buffer.writeShort(Int16(truncatingIfNeeded: utf8Count + MemoryLayout<Int32>.size))
                    try buffer.writeUTF8(val, maxLength: Self.maxHeaderStringLength)
                case .unknown(let dt, let payload):
                    guard dt >= HeaderLayout.propertyTypeMin && dt <= HeaderLayout.propertyTypeMax && (dt < HeaderConstants.dataTypeInt || dt > HeaderConstants.dataTypeString) else {
                        throw WireError.invalidFieldValue(owner: "WireDocument", field: "headerPropertyDataType", detail: "Unknown dataType \(dt) out of range")
                    }
                    guard payload.count <= Int(UInt16.max) else {
                        throw WireError.lengthOutOfRange(field: "headerUnknownProperty", length: payload.count, min: nil, max: Int(UInt16.max))
                    }
                    buffer.writeShort(Int16(truncatingIfNeeded: (prop.key & HeaderLayout.propertyKeyMask) | ((dt & HeaderLayout.propertyTypeMask) << HeaderLayout.propertyTypeShift)))
                    buffer.writeShort(Int16(truncatingIfNeeded: payload.count))
                    buffer.writeBytes(payload)
                }
            }
        } else {
            buffer.writeInt(majorVersion)
            buffer.writeInt(minorVersion)
            buffer.writeInt(patchVersion)
            buffer.writeInt(width)
            buffer.writeInt(height)
            buffer.writeLong(capabilities)
        }

        for op in operations {
            try op.write(to: &buffer)
        }
        return buffer.data
    }
